##################################################################
# Author: Lucas Carter
# PI: Vadim Backman
# Description:
# Plots read 2 3' end termination pileups within introns
# and exons from position files generated by euseq_termination.sh
#
# Plots 1-4 (original, WT only):
#   1. Intron termination by intron length, absolute bp
#      Facets: Short (<1kb), Average (1-10kb), Long (>10kb)
#   2. Exon termination by exon length (control), absolute bp
#      Facets: Short (<200bp), Average (200-500bp), Long (>500bp)
#   3. Intron termination by intron length, relative position (%)
#   4. Exon termination by exon length (control), relative position (%)
#
# Plots in section 7 (WT only, run for High and Low/Unexpressed
# expression separately): same length categories as Plots 1-4,
# restricted to one WT-TPM expression tertile at a time. All 4
# style combinations (intron-bp, intron-%, exon-bp, exon-%) per
# expression filter — 8 plots total.
#
# Plots in section 8 (WT only): same 4 style combinations, but
# faceted by expression level (Low/Unexpressed, Medium, High)
# instead of intron/exon length.
#
# Plot in section 9: WT vs POLR2A comparison for the core
# intron-by-length analysis (Plot 1's structure, both conditions
# shown together instead of WT only).
##################################################################

suppressPackageStartupMessages({
  library(dplyr)
  library(readr)
  library(tidyr)
  library(ggplot2)
  library(scales)
})

##--------------------------------------------------------------## 1. Parameters

TERM_DIR  <- "/projects/b1042/BackmanLab/Lucas/090124_euseq/euseq_pipeline/termination"
EXPR_FILE <- "/projects/b1042/BackmanLab/Lucas/eric_splicing/expr/WT_averaged_TPM.tsv"

POLR2A_SAMPLES <- c("POLR2A_1","POLR2A_2","POLR2A_3")
WT_SAMPLES     <- c("WT_1","WT_2","WT_3")
ALL_SAMPLES    <- c(POLR2A_SAMPLES, WT_SAMPLES)

INTRON_N_BINS <- 100
EXON_N_BINS   <- 50    ## reduced for smoother exon curve

## Total RNA-seq scale factors — WT-anchored
## Applied to POLR2A position counts before computing fractions
SCALE_FACTORS <- c(
  POLR2A_1 = 0.747437, POLR2A_2 = 0.747437, POLR2A_3 = 0.747437,
  WT_1     = 1.000000, WT_2     = 1.000000, WT_3     = 1.000000
)

INTRON_CATS <- c("Short (<1kb)","Average (1-10kb)","Long (>10kb)")
EXON_CATS   <- c("Short Exons","Average Exons","Long Exons")
EXPR_CATS   <- c("Low/Unexpressed","Medium","High")

CONDITION_COLORS <- c(WT = "#88CCEE", POLR2A = "#CC6677")

base_theme <- theme_classic(base_size = 13) +
  theme(
    legend.position    = "right",
    legend.title       = element_blank(),
    plot.title         = element_text(face = "bold", size = 14),
    plot.subtitle      = element_text(color = "grey40", size = 11),
    strip.background   = element_rect(fill = "grey95", color = "grey60"),
    strip.text         = element_text(face = "bold", size = 11),
    panel.grid.major.x = element_line(color = "grey90", linewidth = 0.3),
    panel.grid.major.y = element_line(color = "grey90", linewidth = 0.3)
  )

##--------------------------------------------------------------## 2. Load position files

message("Loading position files...")

load_positions <- function(interval_type, sample_name) {
  path <- file.path(TERM_DIR, interval_type,
                    paste0(sample_name, "_", interval_type,
                           "_positions.txt"))
  if (!file.exists(path)) {
    warning("File not found: ", path)
    return(NULL)
  }
  read_tsv(path,
           col_names = c("gene_id","interval_length","position","strand"),
           col_types = "cddc",
           show_col_types = FALSE) %>%
    dplyr::mutate(sample = sample_name)
}

intron_pos <- dplyr::bind_rows(lapply(ALL_SAMPLES, function(s) {
  df <- load_positions("intron", s)
  if (!is.null(df)) df$scale_factor <- SCALE_FACTORS[s]
  df
}))
exon_pos   <- dplyr::bind_rows(lapply(ALL_SAMPLES, function(s) {
  df <- load_positions("exon", s)
  if (!is.null(df)) df$scale_factor <- SCALE_FACTORS[s]
  df
}))

cat("Intron positions loaded:", nrow(intron_pos), "\n")
cat("Exon positions loaded:  ", nrow(exon_pos),   "\n")

##--------------------------------------------------------------## 3. Categorize and assign condition

intron_pos <- intron_pos %>%
  dplyr::mutate(
    intron_cat = dplyr::case_when(
      interval_length <  1000  ~ "Short (<1kb)",
      interval_length <= 10000 ~ "Average (1-10kb)",
      TRUE                     ~ "Long (>10kb)"
    ),
    intron_cat = factor(intron_cat, levels = INTRON_CATS),
    condition  = factor(
      ifelse(sample %in% POLR2A_SAMPLES, "POLR2A", "WT"),
      levels = c("WT","POLR2A"))
  )

exon_pos <- exon_pos %>%
  dplyr::mutate(
    exon_cat  = dplyr::case_when(
      interval_length <  200 ~ "Short Exons",
      interval_length <= 500 ~ "Average Exons",
      TRUE                   ~ "Long Exons"
    ),
    exon_cat  = factor(exon_cat, levels = EXON_CATS),
    condition = factor(
      ifelse(sample %in% POLR2A_SAMPLES, "POLR2A", "WT"),
      levels = c("WT","POLR2A"))
  )

cat("\nIntron positions by category and condition:\n")
print(table(intron_pos$intron_cat, intron_pos$condition))
cat("\nExon positions by category and condition:\n")
print(table(exon_pos$exon_cat, exon_pos$condition))

##--------------------------------------------------------------## 3b. Load WT TPM and assign expression bins
## Same tertile convention used in the effective E/I ratio script:
## bottom-tertile-of-expressed + all TPM==0/NA genes -> Low/Unexpressed.
## Joined onto intron_pos (which already has intron_cat/condition from
## section 3), producing intron_pos_annotated with BOTH intron_cat and
## expr_bin available simultaneously.

message("\nLoading WT TPM and computing expression tertiles...")

tpm_df <- read_tsv(EXPR_FILE, show_col_types = FALSE) %>%
  dplyr::select(gene_id, TPM) %>%
  dplyr::mutate(gene_id = sub("\\..*", "", gene_id))

expressed_tpm <- tpm_df %>% dplyr::filter(!is.na(TPM), TPM > 0) %>% dplyr::pull(TPM)
tpm_medium <- quantile(expressed_tpm, 1/3, na.rm = TRUE)
tpm_high   <- quantile(expressed_tpm, 2/3, na.rm = TRUE)

tpm_df <- tpm_df %>%
  dplyr::mutate(
    expr_bin = dplyr::case_when(
      is.na(TPM) | TPM == 0 ~ "Low/Unexpressed",
      TPM <= tpm_medium     ~ "Low/Unexpressed",
      TPM <= tpm_high       ~ "Medium",
      TRUE                  ~ "High"
    ),
    expr_bin = factor(expr_bin, levels = EXPR_CATS)
  )

cat("Expression bins (all genes with TPM data):\n")
print(table(tpm_df$expr_bin))

intron_pos_annotated <- intron_pos %>%
  dplyr::mutate(gene_id = sub("\\..*", "", gene_id)) %>%
  dplyr::left_join(tpm_df %>% dplyr::select(gene_id, expr_bin), by = "gene_id")

n_matched_genes   <- intron_pos_annotated %>% dplyr::filter(!is.na(expr_bin)) %>% dplyr::distinct(gene_id) %>% nrow()
n_unmatched_genes <- intron_pos_annotated %>% dplyr::filter(is.na(expr_bin))  %>% dplyr::distinct(gene_id) %>% nrow()
cat("\nIntron positions matched to a WT TPM expression bin:", n_matched_genes, "genes\n")
cat("Intron positions with NO TPM match (excluded from expression-based plots):",
    n_unmatched_genes, "genes\n")
cat("\nIntron positions by expression bin and condition:\n")
print(table(intron_pos_annotated$expr_bin, intron_pos_annotated$condition, useNA = "no"))

## Same join, applied to exon_pos — needed for the exon-control
## versions of the expression-stratified plots below.
exon_pos_annotated <- exon_pos %>%
  dplyr::mutate(gene_id = sub("\\..*", "", gene_id)) %>%
  dplyr::left_join(tpm_df %>% dplyr::select(gene_id, expr_bin), by = "gene_id")

n_matched_exon_genes <- exon_pos_annotated %>% dplyr::filter(!is.na(expr_bin)) %>% dplyr::distinct(gene_id) %>% nrow()
cat("\nExon positions matched to a WT TPM expression bin:", n_matched_exon_genes, "genes\n")
cat("Exon positions by expression bin and condition:\n")
print(table(exon_pos_annotated$expr_bin, exon_pos_annotated$condition, useNA = "no"))

##--------------------------------------------------------------## 4. Bin and compute fraction

bin_positions <- function(pos_df, cat_col, n_bins, relative = FALSE) {
  
  cats       <- levels(pos_df[[cat_col]])
  conditions <- levels(pos_df$condition)
  
  dplyr::bind_rows(lapply(cats, function(cat) {
    dplyr::bind_rows(lapply(conditions, function(cond) {
      
      sub_df <- pos_df %>%
        dplyr::filter(!!rlang::sym(cat_col) == cat,
                      condition == cond)
      
      if (nrow(sub_df) == 0) return(NULL)
      
      if (relative) {
        ## Clip to [0,1] to handle floating point edge cases
        positions <- pmin(pmax(sub_df$position, 0), 1)
        breaks    <- seq(-0.0001, 1.0001, length.out = n_bins + 1)
      } else {
        max_pos   <- quantile(sub_df$position, 0.99, na.rm = TRUE)
        breaks    <- seq(-1, max_pos * 1.001, length.out = n_bins + 1)
        positions <- sub_df$position[sub_df$position <= max_pos]
      }
      
      bin_centers <- (breaks[-1] + breaks[-length(breaks)]) / 2
      counts      <- hist(positions, breaks = breaks, plot = FALSE)$counts
      
      ## Apply scale factor — use mean SF for condition
      ## (all replicates within a condition have the same SF)
      sf    <- mean(sub_df$scale_factor, na.rm = TRUE)
      counts_scaled <- counts * sf
      
      frac  <- counts_scaled / sum(counts_scaled)
      
      data.frame(
        bin_center  = bin_centers,
        fraction    = frac,
        category    = cat,
        condition   = cond,
        n_positions = nrow(sub_df),
        mean_len    = mean(sub_df$interval_length, na.rm = TRUE),
        stringsAsFactors = FALSE
      )
    }))
  }))
}

message("Binning intron positions...")
intron_pileup <- bin_positions(intron_pos, "intron_cat",
                               INTRON_N_BINS, relative = FALSE) %>%
  dplyr::mutate(category  = factor(category,  levels = INTRON_CATS),
                condition = factor(condition, levels = c("WT","POLR2A")))

message("Binning exon positions...")
exon_pileup <- bin_positions(exon_pos, "exon_cat",
                             EXON_N_BINS, relative = TRUE) %>%
  dplyr::mutate(category  = factor(category,  levels = EXON_CATS),
                condition = factor(condition, levels = c("WT","POLR2A")))

##--------------------------------------------------------------## 4b. Generic pileup / label / plot helpers
## Used by every expression-stratified and WT-vs-POLR2A comparison
## plot below (sections 7-9). Plots 1-4 above are left exactly as
## they were, using their original bespoke code — these helpers
## generalize the identical logic for reuse rather than duplicating
## it another 9+ times.

compute_pileup <- function(sub_df, cat_col, cat_levels, n_bins, relative) {
  bin_positions(sub_df, cat_col, n_bins, relative = relative) %>%
    dplyr::mutate(category  = factor(category,  levels = cat_levels),
                  condition = factor(condition, levels = c("WT","POLR2A")))
}

compute_pileup_labels <- function(pileup, sub_df, cat_col, len_label = "mean",
                                  interval_noun = "intervals") {
  cat_sym <- rlang::sym(cat_col)
  
  ## n_intervals counts distinct (category, interval_length, gene_id) rows —
  ## i.e. distinct introns/exons, since a single gene contributes one row
  ## PER interval it has in that category, not one row total.
  interval_counts <- sub_df %>%
    dplyr::distinct(!!cat_sym, interval_length, gene_id) %>%
    dplyr::count(!!cat_sym) %>%
    dplyr::rename(category = !!cat_sym, n_intervals = n)
  
  ## n_genes counts distinct genes contributing at least one interval to
  ## that category — this is what "how many genes" actually means.
  gene_counts <- sub_df %>%
    dplyr::distinct(!!cat_sym, gene_id) %>%
    dplyr::count(!!cat_sym) %>%
    dplyr::rename(category = !!cat_sym, n_genes = n)
  
  pileup %>%
    dplyr::distinct(category, mean_len) %>%
    dplyr::left_join(interval_counts, by = "category") %>%
    dplyr::left_join(gene_counts, by = "category") %>%
    dplyr::slice_head(n = 1, by = category) %>%
    dplyr::mutate(label = paste0(
      "n ", interval_noun, " = ", scales::comma(n_intervals),
      " (", scales::comma(n_genes), " genes)",
      "\n", len_label, " = ", round(mean_len), " bp"
    ))
}

bp_x_scale  <- scale_x_continuous(labels = scales::comma)
pct_x_scale <- scale_x_continuous(labels = function(x) paste0(x, "%"),
                                  breaks = c(0, 25, 50, 75, 100))

## conditions_to_show defaults to "WT" only, matching Plots 1-4's
## existing behavior. Pass c("WT","POLR2A") to compare both.
plot_pileup_generic <- function(pileup, labels, x_var, x_label, x_scale,
                                title, subtitle, conditions_to_show = "WT") {
  plot_df <- pileup %>% dplyr::filter(condition %in% conditions_to_show)
  
  p <- ggplot(plot_df, aes(x = .data[[x_var]], y = fraction, color = condition)) +
    geom_line(linewidth = 0.8) +
    geom_text(data = labels, aes(x = -Inf, y = Inf, label = label),
              hjust = -0.05, vjust = 1.3, size = 3.5, color = "grey30",
              inherit.aes = FALSE) +
    scale_color_manual(values = CONDITION_COLORS, drop = FALSE) +
    x_scale +
    scale_y_continuous(labels = scales::percent) +
    facet_wrap(~ category, nrow = 1, scales = "free_x") +
    labs(x = x_label, y = "Fraction of reads", title = title, subtitle = subtitle) +
    base_theme
  
  print(p)
  invisible(p)
}

## Intron pileups are built with relative=FALSE (native bp positions);
## the "% of intron" view is a post-hoc group-wise rescale of those
## same bp bins — matches Plot 3's original approach exactly.
add_intron_pct <- function(pileup) {
  pileup %>%
    dplyr::group_by(category, condition) %>%
    dplyr::mutate(bin_pct = bin_center / max(bin_center) * 100) %>%
    dplyr::ungroup()
}

## Exon pileups are built with relative=TRUE (native 0-1 positions);
## both the "bp" view and the "%" view are post-hoc unit conversions
## of that same relative binning — matches Plots 2 & 4's original
## approach exactly.
add_exon_bp_and_pct <- function(pileup) {
  pileup %>%
    dplyr::mutate(bin_center_bp = bin_center * mean_len,
                  bin_pct       = bin_center * 100)
}

