    by = "category"
  ) %>%
  dplyr::slice_head(n = 1, by = category) %>%   ## one row per category only
  dplyr::mutate(label = paste0("n = ", scales::comma(n_intervals),
                               "\nmean = ", round(mean_len), " bp"))

exon_labels <- exon_pileup %>%
  dplyr::distinct(category, mean_len) %>%
  dplyr::left_join(
    exon_pos %>%
      dplyr::distinct(exon_cat, interval_length, gene_id) %>%
      dplyr::count(exon_cat) %>%
      dplyr::rename(category = exon_cat, n_intervals = n),
    by = "category"
  ) %>%
  dplyr::slice_head(n = 1, by = category) %>%   ## one row per category only
  dplyr::mutate(label = paste0("n = ", scales::comma(n_intervals),
                               "\nmean = ", round(mean_len), " bp"))

