##--------------------------------------------------------------## 7. Intron AND exon termination by length, split by expression
## Same length categories as Plots 1/2, restricted to one WT-TPM
## expression tertile at a time. Produces all 4 style combinations
## (intron-bp, intron-%, exon-bp, exon-%) per expression filter.
## Preserves the WT-only filter used by Plots 1-4 (see note at top
## of script) — the WT-vs-POLR2A comparison is in section 9.

message("\nBuilding length-stratified termination plots, split by expression...")

plot_length_by_expr_all_styles <- function(expr_filter, expr_label) {
  
  intron_sub <- intron_pos_annotated %>% dplyr::filter(expr_bin == expr_filter)
  exon_sub   <- exon_pos_annotated   %>% dplyr::filter(expr_bin == expr_filter)
  
  n_intron_genes <- intron_sub %>% dplyr::distinct(gene_id) %>% nrow()
  n_exon_genes   <- exon_sub   %>% dplyr::distinct(gene_id) %>% nrow()
  message("  ", expr_label, ": ", nrow(intron_sub), " intron positions (",
          n_intron_genes, " genes), ", nrow(exon_sub), " exon positions (",
          n_exon_genes, " genes)")
  
  if (nrow(intron_sub) == 0 || nrow(exon_sub) == 0) {
    message("  Skipping ", expr_label, " — insufficient data.")
    return(invisible(NULL))
  }
  
  subtitle_suffix <- paste0(expr_label, " WT TPM tertile")
  
  ## Intron — bp
  intron_pileup_e <- compute_pileup(intron_sub, "intron_cat", INTRON_CATS, INTRON_N_BINS, relative = FALSE)
  intron_labels_e <- compute_pileup_labels(intron_pileup_e, intron_sub, "intron_cat",
                                           interval_noun = "introns")
  plot_pileup_generic(
    intron_pileup_e, intron_labels_e, "bin_center",
    "Nucleotide position inside intron (bp)", bp_x_scale,
    paste0("Read termination pileup within introns by intron length \u2014 ", expr_label, " expression"),
    paste0("Read 2 3' end positions  |  EU-seq POLR2A degradation vs WT  |  ",
           subtitle_suffix, "  |  n = ", n_intron_genes, " genes"),
    conditions_to_show = c("WT","POLR2A")
  )
  
  ## Intron — %
  intron_pileup_e_pct <- add_intron_pct(intron_pileup_e)
  plot_pileup_generic(
    intron_pileup_e_pct, intron_labels_e, "bin_pct",
    "Intron coverage fraction", pct_x_scale,
    paste0("Read termination pileup within introns \u2014 relative position \u2014 ", expr_label, " expression"),
    paste0("Read 2 3' end positions  |  EU-seq POLR2A degradation vs WT  |  ",
           subtitle_suffix, "  |  n = ", n_intron_genes, " genes"),
    conditions_to_show = c("WT","POLR2A")
  )
  
  ## Exon — bp (control)
  exon_pileup_e <- compute_pileup(exon_sub, "exon_cat", EXON_CATS, EXON_N_BINS, relative = TRUE)
  exon_labels_e <- compute_pileup_labels(exon_pileup_e, exon_sub, "exon_cat",
                                         interval_noun = "exons")
  exon_pileup_e_view <- add_exon_bp_and_pct(exon_pileup_e)
  plot_pileup_generic(
    exon_pileup_e_view, exon_labels_e, "bin_center_bp",
    "Nucleotide position inside exon (bp)", bp_x_scale,
    paste0("Read termination pileup within exons by exon length (control) \u2014 ", expr_label, " expression"),
    paste0("Read 2 3' end positions  |  EU-seq POLR2A degradation vs WT  |  ",
           subtitle_suffix, "  |  n = ", n_exon_genes, " genes"),
    conditions_to_show = c("WT","POLR2A")
  )
  
  ## Exon — % (control)
  plot_pileup_generic(
    exon_pileup_e_view, exon_labels_e, "bin_pct",
    "Exon coverage fraction", pct_x_scale,
    paste0("Read termination pileup within exons \u2014 relative position (control) \u2014 ", expr_label, " expression"),
    paste0("Read 2 3' end positions  |  EU-seq POLR2A degradation vs WT  |  ",
           subtitle_suffix, "  |  n = ", n_exon_genes, " genes"),
    conditions_to_show = c("WT","POLR2A")
  )
  
  invisible(NULL)
}

message("\n\u2500\u2500 Length-stratified termination: High expression only \u2500\u2500")
plot_length_by_expr_all_styles("High", "High")

message("\n\u2500\u2500 Length-stratified termination: Low/Unexpressed only \u2500\u2500")
plot_length_by_expr_all_styles("Low/Unexpressed", "Low/Unexpressed")

